<template><section class="container-main section-padding"><form class="pc-card mx-auto max-w-xl space-y-4" @submit.prevent="submit"><p class="pc-kicker">{{ $t('authP.supplierWorkspace') }}</p><h1 class="text-3xl font-bold text-white">{{ $t('authP.createSupplier') }}</h1><input v-model="form.full_name" class="input-field" required :placeholder="$t('authP.ownerName')"/><input v-model="form.email" class="input-field" type="email" required :placeholder="$t('auth.email')"/><input v-model="form.phone" class="input-field" :placeholder="$t('supTeam.phonePh')"/><input v-model="form.company_name" class="input-field" required :placeholder="$t('authP.supplierCompany')"/><input v-model="form.country" class="input-field" :placeholder="$t('portal.account.country')"/><input v-model="form.password" class="input-field" type="password" minlength="8" required :placeholder="$t('auth.password')"/><p v-if="error" class="text-red-300">{{ error }}</p><button class="btn-primary w-full" :disabled="loading">{{ loading ? $t('pTickets.creating') : $t('authP.createSupplierBtn') }}</button></form></section></template>
<script setup lang="ts">
const { t } = useI18n();definePageMeta({middleware:'guest'});const {register}=useAuth();const loading=ref(false);const error=ref('');const form=reactive({full_name:'',email:'',phone:'',company_name:'',country:'',password:'',role:'vendor',company_type:'supplier'});async function submit(){loading.value=true;try{await register(form);await navigateTo('/supplier-onboarding')}catch(e:any){error.value=e?.data?.detail||e?.message}finally{loading.value=false}}</script>
